-- Run in the Neon SQL Editor. Neon creates the database itself.
CREATE TABLE IF NOT EXISTS roles (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(50) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, role_id BIGINT NOT NULL REFERENCES roles(id), name VARCHAR(120) NOT NULL, email VARCHAR(190) UNIQUE NOT NULL, mobile VARCHAR(20), password_hash VARCHAR(255) NOT NULL, status VARCHAR(20) DEFAULT 'active' CHECK (status IN ('active','disabled')), created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS customers (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT UNIQUE NOT NULL REFERENCES users(id), company_name VARCHAR(160), address JSONB);
CREATE TABLE IF NOT EXISTS technicians (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT UNIQUE NOT NULL REFERENCES users(id), service_areas JSONB, location_sharing BOOLEAN DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS products (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(160) NOT NULL, category VARCHAR(100), description TEXT, pricing_method VARCHAR(20) NOT NULL CHECK (pricing_method IN ('sqft','unit','fixed')), status BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS pricing_rules (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id BIGINT REFERENCES products(id), rule_type VARCHAR(50), amount NUMERIC(12,2) NOT NULL, tax_rate NUMERIC(5,2) DEFAULT 18, active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS orders (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_no VARCHAR(30) UNIQUE NOT NULL, customer_id BIGINT NOT NULL REFERENCES customers(id), specifications JSONB NOT NULL, estimated_price NUMERIC(12,2), status VARCHAR(40) DEFAULT 'under_review', created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quotations (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, quotation_no VARCHAR(30) UNIQUE NOT NULL, order_id BIGINT NOT NULL REFERENCES orders(id), subtotal NUMERIC(12,2), discount NUMERIC(12,2), gst NUMERIC(12,2), final_amount NUMERIC(12,2) NOT NULL, terms TEXT, valid_until DATE, admin_approved_at TIMESTAMPTZ, status VARCHAR(30));
CREATE TABLE IF NOT EXISTS service_tickets (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ticket_no VARCHAR(30) UNIQUE NOT NULL, customer_id BIGINT NOT NULL REFERENCES customers(id), category VARCHAR(80), description TEXT, location JSONB, photos JSONB, priority VARCHAR(20), status VARCHAR(40) DEFAULT 'submitted', created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS technician_jobs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ticket_id BIGINT NOT NULL REFERENCES service_tickets(id), technician_id BIGINT REFERENCES technicians(id), status VARCHAR(40), scheduled_at TIMESTAMPTZ, evidence JSONB, customer_confirmation JSONB);
CREATE TABLE IF NOT EXISTS sign_board_assets (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, asset_no VARCHAR(20) UNIQUE NOT NULL, customer_id BIGINT NOT NULL REFERENCES customers(id), details JSONB NOT NULL, location JSONB, warranty_until DATE, qr_token CHAR(64) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS notifications (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), channel VARCHAR(20), title VARCHAR(160), body TEXT, read_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS device_tokens (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,token TEXT UNIQUE NOT NULL,platform VARCHAR(20) DEFAULT 'web',active BOOLEAN DEFAULT TRUE,last_seen_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notification_templates (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(120) NOT NULL,event_key VARCHAR(120) UNIQUE NOT NULL,title VARCHAR(160) NOT NULL,body TEXT NOT NULL,channels JSONB DEFAULT '["push"]'::jsonb,status BOOLEAN DEFAULT TRUE,updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE notification_templates ADD COLUMN IF NOT EXISTS category VARCHAR(30) DEFAULT 'order';
CREATE TABLE IF NOT EXISTS notification_deliveries(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT REFERENCES users(id),template_id BIGINT REFERENCES notification_templates(id) ON DELETE SET NULL,channel VARCHAR(20) NOT NULL,title VARCHAR(160),body TEXT,status VARCHAR(20) NOT NULL,provider_id VARCHAR(255),error_message TEXT,attempted_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_notification_deliveries_created ON notification_deliveries(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_device_tokens_user ON device_tokens(user_id,active);
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT REFERENCES users(id), action VARCHAR(100), entity_type VARCHAR(60), entity_id BIGINT, metadata JSONB, created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS job_status_history (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, job_id BIGINT NOT NULL REFERENCES technician_jobs(id), status VARCHAR(40) NOT NULL, notes TEXT, created_by BIGINT REFERENCES users(id), created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS job_photos (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, job_id BIGINT NOT NULL REFERENCES technician_jobs(id), photo_type VARCHAR(20) NOT NULL CHECK (photo_type IN ('before','work','after')), storage_key VARCHAR(255) NOT NULL, mime_type VARCHAR(80), created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS settings (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, setting_key VARCHAR(120) UNIQUE NOT NULL, value JSONB NOT NULL, updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS permissions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) UNIQUE NOT NULL, description VARCHAR(255));
CREATE TABLE IF NOT EXISTS role_permissions (role_id BIGINT NOT NULL REFERENCES roles(id) ON DELETE CASCADE, permission_id BIGINT NOT NULL REFERENCES permissions(id) ON DELETE CASCADE, PRIMARY KEY(role_id,permission_id));
CREATE TABLE IF NOT EXISTS order_items (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id BIGINT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,product_id BIGINT REFERENCES products(id),description TEXT,quantity NUMERIC(10,2) DEFAULT 1,unit_price NUMERIC(12,2),amount NUMERIC(12,2));
CREATE TABLE IF NOT EXISTS quotation_items (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,quotation_id BIGINT NOT NULL REFERENCES quotations(id) ON DELETE CASCADE,description TEXT NOT NULL,quantity NUMERIC(10,2) DEFAULT 1,unit_price NUMERIC(12,2),amount NUMERIC(12,2));
CREATE TABLE IF NOT EXISTS asset_service_history (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,asset_id BIGINT NOT NULL REFERENCES sign_board_assets(id) ON DELETE CASCADE,ticket_id BIGINT REFERENCES service_tickets(id),notes TEXT,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE asset_service_history ADD COLUMN IF NOT EXISTS history_type VARCHAR(20) DEFAULT 'service';
CREATE TABLE IF NOT EXISTS qr_codes (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,asset_id BIGINT UNIQUE NOT NULL REFERENCES sign_board_assets(id) ON DELETE CASCADE,token CHAR(64) UNIQUE NOT NULL,active BOOLEAN DEFAULT TRUE,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
INSERT INTO qr_codes(asset_id,token,active) SELECT id,qr_token,TRUE FROM sign_board_assets ON CONFLICT(asset_id) DO NOTHING;
CREATE TABLE IF NOT EXISTS ai_conversations (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT REFERENCES users(id),question TEXT NOT NULL,response TEXT,escalation_status VARCHAR(30) DEFAULT 'none',created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ai_leads (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,customer_id BIGINT REFERENCES customers(id),requirement TEXT,product VARCHAR(160),estimated_budget NUMERIC(12,2),contact VARCHAR(190),status VARCHAR(30) DEFAULT 'new',created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ai_knowledge_base (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title VARCHAR(180) NOT NULL,category VARCHAR(80),content TEXT NOT NULL,status BOOLEAN DEFAULT TRUE,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE ai_knowledge_base ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP;
CREATE EXTENSION IF NOT EXISTS vector;
ALTER TABLE ai_knowledge_base ADD COLUMN IF NOT EXISTS embedding vector(3072);
CREATE INDEX IF NOT EXISTS idx_ai_knowledge_embedding ON ai_knowledge_base USING hnsw (embedding vector_cosine_ops);
CREATE TABLE IF NOT EXISTS ai_settings(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,key VARCHAR(100) UNIQUE NOT NULL,value JSONB NOT NULL,updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ai_jobs(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,kind VARCHAR(60) NOT NULL,status VARCHAR(30) DEFAULT 'queued',payload JSONB NOT NULL,result JSONB,error TEXT,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS design_categories(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(120) UNIQUE NOT NULL,status BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS design_styles(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(120) UNIQUE NOT NULL,description TEXT,status BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS design_prompt_templates(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(120) UNIQUE NOT NULL,template TEXT NOT NULL,supported_sign_types JSONB DEFAULT '[]'::jsonb,status BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS example_designs(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title VARCHAR(160) NOT NULL,category_id BIGINT REFERENCES design_categories(id),style_id BIGINT REFERENCES design_styles(id),sign_type VARCHAR(120),image_url TEXT,prompt TEXT,status BOOLEAN DEFAULT TRUE,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE design_concepts ADD COLUMN IF NOT EXISTS quotation_id BIGINT REFERENCES quotations(id);
ALTER TABLE design_concepts ADD COLUMN IF NOT EXISTS order_id BIGINT REFERENCES orders(id);
CREATE TABLE IF NOT EXISTS design_requests (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,customer_id BIGINT REFERENCES customers(id),order_id BIGINT REFERENCES orders(id),requirements JSONB NOT NULL,status VARCHAR(30) DEFAULT 'requested',created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS design_concepts (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,request_id BIGINT REFERENCES design_requests(id) ON DELETE CASCADE,image_url TEXT,prompt TEXT,status VARCHAR(30) DEFAULT 'concept',admin_notes TEXT,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,quotation_id BIGINT REFERENCES quotations(id),amount NUMERIC(12,2) NOT NULL,status VARCHAR(30),reference VARCHAR(120),created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reviews (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,customer_id BIGINT REFERENCES customers(id),job_id BIGINT REFERENCES technician_jobs(id),rating SMALLINT CHECK(rating BETWEEN 1 AND 5),comment TEXT,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE users ADD COLUMN IF NOT EXISTS verified_at TIMESTAMPTZ;
ALTER TABLE users ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP;
CREATE TABLE IF NOT EXISTS customer_addresses (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,customer_id BIGINT NOT NULL REFERENCES customers(id) ON DELETE CASCADE,label VARCHAR(60) DEFAULT 'Other',address_line TEXT NOT NULL,city VARCHAR(100),state VARCHAR(100),pincode VARCHAR(10),latitude NUMERIC(10,7),longitude NUMERIC(10,7),is_default BOOLEAN DEFAULT FALSE,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
INSERT INTO customer_addresses(customer_id,label,address_line,city,state,pincode,is_default)
SELECT c.id,'Primary',c.address->>'addressLine',c.address->>'city',c.address->>'state',c.address->>'pincode',TRUE
FROM customers c
WHERE NULLIF(c.address->>'addressLine','') IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM customer_addresses ca WHERE ca.customer_id=c.id);
CREATE TABLE IF NOT EXISTS auth_otps (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,purpose VARCHAR(30) NOT NULL,otp_hash VARCHAR(255) NOT NULL,expires_at TIMESTAMPTZ NOT NULL,consumed_at TIMESTAMPTZ,attempts SMALLINT DEFAULT 0,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS revoked_tokens (jti VARCHAR(80) PRIMARY KEY,user_id BIGINT REFERENCES users(id) ON DELETE CASCADE,expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS support_escalations (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,conversation_id BIGINT REFERENCES ai_conversations(id),user_id BIGINT REFERENCES users(id),reason TEXT,status VARCHAR(30) DEFAULT 'open',created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE design_requests ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE service_tickets ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE quotations ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE quotations ADD COLUMN IF NOT EXISTS installation NUMERIC(12,2) DEFAULT 0;
ALTER TABLE quotations ADD COLUMN IF NOT EXISTS transportation NUMERIC(12,2) DEFAULT 0;
ALTER TABLE quotations ADD COLUMN IF NOT EXISTS gst_rate NUMERIC(5,2) DEFAULT 18;
CREATE INDEX IF NOT EXISTS idx_customer_addresses_customer ON customer_addresses(customer_id);
CREATE INDEX IF NOT EXISTS idx_notifications_user_created ON notifications(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_auth_otps_user_purpose ON auth_otps(user_id,purpose,created_at DESC);
ALTER TABLE sign_board_assets ADD COLUMN IF NOT EXISTS created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP;
CREATE OR REPLACE VIEW customer_directory AS SELECT c.id,u.name,u.email,u.mobile,c.company_name,c.address,u.status,u.created_at FROM customers c JOIN users u ON u.id=c.user_id;
CREATE OR REPLACE VIEW technician_directory AS SELECT t.id,u.name,u.email,u.mobile,t.service_areas,u.status,u.created_at FROM technicians t JOIN users u ON u.id=t.user_id;
CREATE OR REPLACE VIEW quotation_directory AS SELECT q.id,q.quotation_no AS "quotationNo",o.order_no AS "orderNo",q.final_amount AS "finalAmount",q.valid_until AS "validUntil",q.status FROM quotations q JOIN orders o ON o.id=q.order_id;
CREATE OR REPLACE VIEW asset_directory AS SELECT a.id,a.asset_no AS "assetNo",u.name AS customer,a.details,a.location,a.warranty_until AS "warrantyUntil",a.created_at AS "createdAt" FROM sign_board_assets a JOIN customers c ON c.id=a.customer_id JOIN users u ON u.id=c.user_id;
CREATE OR REPLACE VIEW notification_directory AS SELECT n.id,u.email,n.channel,n.title,n.body,n.read_at AS "readAt",n.created_at AS "createdAt" FROM notifications n JOIN users u ON u.id=n.user_id;
