ALTER TABLE lighting_options ADD COLUMN IF NOT EXISTS image_url TEXT;
ALTER TABLE lighting_options ADD COLUMN IF NOT EXISTS pricing_method VARCHAR(20) DEFAULT 'sqft';
ALTER TABLE accessories ADD COLUMN IF NOT EXISTS image_url TEXT;
ALTER TABLE accessories ADD COLUMN IF NOT EXISTS pricing_method VARCHAR(20) DEFAULT 'unit';
