ALTER TABLE installation_options ADD COLUMN IF NOT EXISTS pricing_method VARCHAR(20) DEFAULT 'fixed';
ALTER TABLE pricing_rules ADD COLUMN IF NOT EXISTS name VARCHAR(120);
ALTER TABLE pricing_rules ADD COLUMN IF NOT EXISTS pricing_method VARCHAR(20) DEFAULT 'fixed';
