-- Technician mobile workflow
ALTER TABLE technicians ADD COLUMN IF NOT EXISTS profile_photo_url TEXT;
ALTER TABLE technicians ADD COLUMN IF NOT EXISTS emergency_contact VARCHAR(20);
ALTER TABLE technicians ADD COLUMN IF NOT EXISTS skills JSONB DEFAULT '[]'::jsonb;
ALTER TABLE technicians ADD COLUMN IF NOT EXISTS last_latitude NUMERIC(10,7);
ALTER TABLE technicians ADD COLUMN IF NOT EXISTS last_longitude NUMERIC(10,7);
ALTER TABLE technicians ADD COLUMN IF NOT EXISTS last_location_at TIMESTAMPTZ;
ALTER TABLE technician_jobs ADD COLUMN IF NOT EXISTS accepted_at TIMESTAMPTZ;
ALTER TABLE technician_jobs ADD COLUMN IF NOT EXISTS travel_started_at TIMESTAMPTZ;
ALTER TABLE technician_jobs ADD COLUMN IF NOT EXISTS reached_at TIMESTAMPTZ;
ALTER TABLE technician_jobs ADD COLUMN IF NOT EXISTS inspection_started_at TIMESTAMPTZ;
ALTER TABLE technician_jobs ADD COLUMN IF NOT EXISTS work_started_at TIMESTAMPTZ;
ALTER TABLE technician_jobs ADD COLUMN IF NOT EXISTS work_completed_at TIMESTAMPTZ;
ALTER TABLE technician_jobs ADD COLUMN IF NOT EXISTS closed_at TIMESTAMPTZ;
