ALTER TABLE service_tickets ADD COLUMN IF NOT EXISTS asset_id BIGINT REFERENCES sign_board_assets(id);
ALTER TABLE job_photos DROP CONSTRAINT IF EXISTS job_photos_photo_type_check;
ALTER TABLE job_photos ADD CONSTRAINT job_photos_photo_type_check CHECK (photo_type IN ('before','damage','work','after'));
ALTER TABLE job_photos ADD COLUMN IF NOT EXISTS uploaded_by BIGINT REFERENCES users(id);

CREATE TABLE IF NOT EXISTS job_materials (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  job_id BIGINT NOT NULL REFERENCES technician_jobs(id) ON DELETE CASCADE,
  name VARCHAR(160) NOT NULL,
  quantity NUMERIC(10,2) NOT NULL CHECK (quantity > 0),
  unit VARCHAR(40) NOT NULL,
  notes TEXT,
  created_by BIGINT REFERENCES users(id),
  created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS job_location_updates (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  job_id BIGINT NOT NULL REFERENCES technician_jobs(id) ON DELETE CASCADE,
  technician_id BIGINT NOT NULL REFERENCES technicians(id),
  latitude NUMERIC(10,7) NOT NULL CHECK (latitude BETWEEN -90 AND 90),
  longitude NUMERIC(10,7) NOT NULL CHECK (longitude BETWEEN -180 AND 180),
  accuracy_meters NUMERIC(8,2),
  created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS job_completion_otps (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  job_id BIGINT NOT NULL REFERENCES technician_jobs(id) ON DELETE CASCADE,
  otp_hash VARCHAR(255) NOT NULL,
  expires_at TIMESTAMPTZ NOT NULL,
  attempts SMALLINT DEFAULT 0,
  consumed_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_job_materials_job ON job_materials(job_id);
CREATE INDEX IF NOT EXISTS idx_job_locations_job_created ON job_location_updates(job_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_job_completion_otps_active ON job_completion_otps(job_id,created_at DESC);

-- Service-area access control and outbound WhatsApp audit trail
CREATE TABLE IF NOT EXISTS allowed_cities (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name VARCHAR(120) NOT NULL,
  state VARCHAR(120),
  country VARCHAR(120) NOT NULL DEFAULT 'India',
  latitude NUMERIC(10,7) NOT NULL CHECK (latitude BETWEEN -90 AND 90),
  longitude NUMERIC(10,7) NOT NULL CHECK (longitude BETWEEN -180 AND 180),
  radius_km NUMERIC(8,2) NOT NULL DEFAULT 25 CHECK (radius_km > 0 AND radius_km <= 500),
  active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(name,state,country)
);
CREATE TABLE IF NOT EXISTS whatsapp_notification_logs (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  job_id BIGINT NOT NULL REFERENCES technician_jobs(id) ON DELETE CASCADE,
  customer_user_id BIGINT REFERENCES users(id),
  event_key VARCHAR(80) NOT NULL,
  recipient VARCHAR(30),
  message TEXT NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','sent','failed','skipped')),
  provider_message_id VARCHAR(255),
  error_message TEXT,
  attempted_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(job_id,event_key)
);
CREATE INDEX IF NOT EXISTS idx_allowed_cities_active ON allowed_cities(active);
CREATE INDEX IF NOT EXISTS idx_whatsapp_logs_created ON whatsapp_notification_logs(created_at DESC);
